// Validación de Identidad y Asignación de Casillero Box Correos Miami
const body = $input.first().json.body || $input.first().json;

const nombre = body.nombre || 'Ciudadano';
const correo = (body.correo || body.email || '').trim().toLowerCase();
const telefono = body.telefono || '+506 8000-0000';
const cedula = body.cedula || '1-0000-0000';

// 1. Generación de Número de Cliente y Casillero Miami (CR-BOX-XXXX)
const clientCode = Math.floor(10000 + Math.random() * 90000);
const casilleroMiami = `CR-MIA-${clientCode}`;
const fechaRegistro = new Date().toISOString().split('T')[0];

return [{
  json: {
    id: `USR-${clientCode}`,
    nombre,
    correo,
    cedula,
    telefono,
    rol: 'Usuario',
    estado: 'Activo',
    fechaRegistro,
    casilleroMiami,
    direccionMiami: `8200 NW 27th St, Suite 104, Miami, FL 33122 (${casilleroMiami})`,
    emailBienvenidaEnviado: true
  }
}];
